/* Hide ERPNext default print title / document number */
.print-heading,
.print-heading h2,
.print-heading .sub-heading {
    display: none !important;
}

@font-face {
    font-family: "MyCustomFont";
    src: url("https://erpnext.ivalueconsult.com/files/DINNextLTArabic-Regular.ttf") format("opentype");
}

* {
    font-family: "MyCustomFont" !important;
    box-sizing: border-box;
}

@page {
    size: A4;
    margin: 8mm;
}

html,
body {
    margin: 0;
    padding: 0;
}

