/*}*/
.page {
    width: 100%;
    page-break-before: always;
    break-before: page;
}

.page:first-of-type {
    page-break-before: auto;
    break-before: auto;
}
.page:last-of-type {
    page-break-after: auto;
    break-after: auto;
}

.header {
    margin-top: 10px;
    margin-bottom: 10px;
}

.footer {
    margin-top: 10px;
}

.header img,
.footer img {
    width: 100%;
    height: auto;
    display: block;
}

.center {
    text-align: center;
    font-weight: bold;
}

.right {
    text-align: right;
    font-weight: bold;
}

.amount {
    text-align: center;
    white-space: nowrap;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th,
td {
    border: 1px solid #2b66c7;signature-block
    padding: 5px 7px;
    vertical-align: middle;
    font-size: 10.5px;
    text-align: center;
    font-weight: bold;
}

.muted {
    color: #6b7280;
}

.stamp-wrap {
    display: flex;
    justify-content: flex-end;
    margin-top: 10px;
    text-align: right;
}

.stamp-wrap img {
    width: 120px;
}

.iban {
    margin-top: 10px;
    font-size: 13px;
}

.money-line {
    direction: rtl;
    unicode-bidi: embed;
}

.empty-line {
    color: #999;
    letter-spacing: 2px;
    font-weight: bold;
}

.financial-block {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.financial-table {
    width: 100%;
    border-collapse: collapse;
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.financial-table tr,
.financial-table td,
.financial-table th,
.stamp-wrap,
.iban {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.financial-table th,
.financial-table td {
    font-size: 10px;
    padding: 0px 0px;
}

.clearance-one-page {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
    font-size: 10px;
    line-height: 1.2;
}

.clearance-one-page p,
.clearance-one-page div,
.clearance-one-page table,
.clearance-one-page tr,
.clearance-one-page td,
.clearance-one-page span {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.clearance-one-page p {
    margin-top: 0 !important;
    margin-bottom: 0px !important;
}

.clearance-one-page h1,
.clearance-one-page h2,
.clearance-one-page h3,
.clearance-one-page h4,
.clearance-one-page .title-ar,
.clearance-one-page .title-en {
    margin-top: 2px !important;
    margin-bottom: 4px !important;
}


  .fnf-page {
    direction: rtl;
    text-align: right;
    padding: 6px;
    font-size: 0.9rem;
    line-height: 1.2;

    page-break-before: always;
  }

  .fnf-header-block {
    page-break-inside: avoid;
  }

  .fnf-title {
    font-weight: 700;
    font-size: 1.2rem;
