    display: block;
  }

  .clearance {
    margin-top: 2px;
  }

  .fnf-body {
    text-align: justify;
    margin-top: 2px;
  }

  .fnf-body p {
    margin: 0 0 6px;
    line-height: 1.45;
  }

  .value {
    font-weight: 700;
  }

  .money {
    font-weight: 700;
    white-space: nowrap;
  }

  .money bdi {
    direction: ltr;
    unicode-bidi: isolate;
    display: inline-block;
  }

  .signature-block {
    margin-top: 10px;
    text-align: center;
    font-size: 0.8rem;
    line-height: 1.4;
    page-break-inside: avoid;
  }

  .signature-block .line {
    margin: 0;
  }
  
