/* Final clearance page - keep on one page */
/* Final clearance page - keep on one page */
.page-clearance {
    direction: rtl !important;
    text-align: right !important;

    page-break-before: always !important;
    break-before: page !important;

    page-break-inside: avoid !important;
    break-inside: avoid !important;

    padding: 0 4mm !important;
    margin: 0 !important;

    font-size: 9px !important;
    line-height: 1.18 !important;

    overflow: visible !important;
}

/* Prevent breaking inside clearance page */
.page-clearance  {
    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

/* Title */
.page-clearance .fnf-title {
    text-align: center !important;
    font-weight: bold !important;
    font-size: 11px !important;
    line-height: 1.15 !important;
    margin: 0 0 4px 0 !important;
}

.page-clearance .fnf-title .line {
    display: block !important;
    text-decoration: underline !important;
}

/* First paragraph */
.page-clearance .clearance {
    direction: rtl !important;
    text-align: justify !important;
    unicode-bidi: embed !important;

    margin: 0 0 4px 0 !important;
    padding: 0 !important;

    font-size: 9.5px !important;
    line-height: 1 !important;
}

/* Body paragraphs */
.page-clearance .fnf-body {
    margin: 0 !important;
    padding: 0 !important;
}

.page-clearance .fnf-body p {
    direction: rtl !important;
    text-align: justify !important;
    unicode-bidi: embed !important;

    margin: 0 0 0 0 !important;
    padding: 0 !important;

    font-size: 9.5px !important;
    line-height: 1 !important;
}

/* Signature */
.page-clearance .signature-block {
    margin-top: 4px !important;
    text-align: center !important;

    font-size: 8.5px !important;
    line-height: 1 !important;

    page-break-inside: avoid !important;
    break-inside: avoid !important;
}

.page-clearance .signature-block .line {
    margin: 0 !important;
}

/* Signature placeholder */
.page-clearance .signature-block div[style*="transform"] {
    transform: scale(1.15) !important;
    transform-origin: center center !important;
}
